    base_threshold = -0.1 + 0.7 * min(1.0, round_num / 50.0)

    # Adjust based on own recent behavior (last 5 actions)
    TARGET = 5
    recent = my_history[-TARGET:] if len(my_history) >= TARGET else my_history
    if recent:
        recent_defects = sum(1 for a in recent if a == 'defect')
        if recent_defects >= 3:  # more defections than cooperations recently
            base_threshold += 0.3  # become stricter

    # Very low reputation never gets cooperation
    if recipient_reputation < -0.5:
        return False

    return recipient_reputation >= base_threshold

